int
krb5int_ucstrncmp(
                  const krb5_unicode * u1,
                  const krb5_unicode * u2,
                  size_t n)
{
    for (; 0 < n; ++u1, ++u2, --n) {
        if (*u1 != *u2) {
            return *u1 < *u2 ? -1 : +1;
        }
        if (*u1 == 0) {
            return 0;
        }
    }
    return 0;
}

int
krb5int_ucstrncasecmp(
                      const krb5_unicode * u1,
                      const krb5_unicode * u2,
                      size_t n)
{
    for (; 0 < n; ++u1, ++u2, --n) {
        krb5_unicode uu1 = uctolower(*u1);
        krb5_unicode uu2 = uctolower(*u2);

        if (uu1 != uu2) {
            return uu1 < uu2 ? -1 : +1;
        }
        if (uu1 == 0) {
            return 0;
        }
    }
    return 0;
}

krb5_unicode *
krb5int_ucstrnchr(
                  const krb5_unicode * u,
                  size_t n,
                  krb5_unicode c)
{
    for (; 0 < n; ++u, --n) {
        if (*u == c) {
            return (krb5_unicode *) u;
        }
    }

    return NULL;
}

krb5_unicode *
krb5int_ucstrncasechr(
                      const krb5_unicode * u,
                      size_t n,
                      krb5_unicode c)
{
    c = uctolower(c);
    for (; 0 < n; ++u, --n) {
        if ((krb5_unicode) uctolower(*u) == c) {
            return (krb5_unicode *) u;
        }
    }

    return NULL;
}

void
krb5int_ucstr2upper(
                    krb5_unicode * u,
                    size_t n)
{
    for (; 0 < n; ++u, --n) {
        *u = uctoupper(*u);
    }
}

#define TOUPPER(c)  (islower(c) ? toupper(c) : (c))
#define TOLOWER(c)  (isupper(c) ? tolower(c) : (c))

